const digest = (text: string): string => createHash("sha256").update(text, "utf8").digest("hex").slice(0, 12);
const pinNamed = (id: string): Pin => {
  const pin = PINS.find(entry => entry.id === id);
  if (pin === undefined) throw new Error(`missing pin ${id}`);
  return pin;
};
const rowNamed = (id: string): Row => {
  const row = ROWS.find(entry => entry.id === id);
  if (row === undefined) throw new Error(`missing row ${id}`);
  return row;
};
/** Every code point the predicate holds for, read over the whole code space. */
function codePointsWhere(holds: (char: string) => boolean): number[] {
  const found: number[] = [];
  for (let point = 0; point <= 0x10ffff; point += 1) if (holds(String.fromCodePoint(point))) found.push(point);
  return found;
}
const hex = (point: number): string => `U+${point.toString(16).toUpperCase().padStart(4, "0")}`;
/** A bead's row in the tracker export, the outside record ANCHOR reads: its description (when it has one) and its notes. */
function exportRow(id: string): { readonly description: string; readonly notes: string } {
  const records: unknown[] = trackerExportText(join(REPO, ".beads/issues.jsonl")).trim().split("\n").map(line => JSON.parse(line) as unknown);
  const row = records.find(value => typeof value === "object" && value !== null && "id" in value && value.id === id);
  if (typeof row !== "object" || row === null || !("notes" in row) || typeof row.notes !== "string") throw new Error(`${id} notes absent`);
  return { description: "description" in row && typeof row.description === "string" ? row.description : "", notes: row.notes };
}
/** A probe's cooked carrier text: a script's first string literal as TypeScript cooks it, a doc's text as written. */
function cooked(probe: Probe): string {
  if (!probe.path.endsWith(".ts")) return probe.text;
  let found: string | undefined;
  const visit = (node: ts.Node): void => {
    if (found === undefined && ts.isStringLiteral(node)) found = node.text;
    ts.forEachChild(node, visit);
  };
  visit(ts.createSourceFile(probe.path, probe.text, ts.ScriptTarget.Latest, true, ts.ScriptKind.TS));
  return found ?? "";
}
/** The wrapper kinds around a probe's "effectClass" key or element argument, outermost first. */
function wrapperChain(probe: Probe): string[] {
  const chains: string[][] = [];
  const kindOf = (node: ts.Expression): string | undefined =>
    ts.isParenthesizedExpression(node) ? "P" : ts.isAsExpression(node) ? "AS" : ts.isSatisfiesExpression(node) ? "SAT" : ts.isNonNullExpression(node) ? "NN" : ts.isTypeAssertionExpression(node) ? "ANG" : undefined;
  const walk = (start: ts.Expression): void => {
    const chain: string[] = [];
    let at = start;
    for (let kind = kindOf(at); kind !== undefined; kind = kindOf(at)) {
      chain.push(kind);
      at = (at as ts.ParenthesizedExpression).expression;
    }
    if (ts.isStringLiteral(at) && at.text === "effectClass") chains.push(chain);
  };
  const visit = (node: ts.Node): void => {
    if (ts.isComputedPropertyName(node)) walk(node.expression);
    if (ts.isElementAccessExpression(node)) walk(node.argumentExpression);
    ts.forEachChild(node, visit);
  };
  visit(ts.createSourceFile(probe.path, probe.text, ts.ScriptTarget.Latest, true, ts.ScriptKind.TS));
  if (chains.length !== 1) throw new Error(`${probe.id}: ${chains.length} effectClass keys`);
  return chains[0] ?? [];
}
/** Whether a chain holds outer directly over inner, or with only parentheses between them (TypeScript needs them between some pairs). */
function holdsPair(chain: readonly string[], outer: string, inner: string): boolean {
  return chain.some((kind, index) => kind === outer && (inner === "P" ? chain[index + 1] === "P" : chain.slice(index + 1).find(entry => entry !== "P") === inner));
}
/** A word's four case forms: lower, Capital, UPPER and aLtErNaTe (odd positions upper). */
const caseForms = (word: string): string[] => [word, word.charAt(0).toUpperCase() + word.slice(1), word.toUpperCase(), [...word].map((char, index) => (index % 2 === 1 ? char.toUpperCase() : char)).join("")];
const escapedWord = (word: string): string => word.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
/** A list as a title spells it: "a, b and c" or "a, b or c". */
const spelled = (names: readonly string[], last: string): string => (names.length < 2 ? names.join("") : `${names.slice(0, -1).join(", ")} ${last} ${names[names.length - 1]}`);
/** A literal under one typed wrapper as a title spells it: an as or satisfies clause follows it, an angle assertion leads it. */
const wrapped = (literal: string, form: string): string => (form.startsWith("<") ? `${form}${literal}` : `${literal} ${form}`);

/**
 * ANCHOR's budget (wb-coyr: F4 of the wb-021.9 landing-912 gate, cmd_5da3b69d9465). ANCHOR reads the bead export through
 * exportRow twice (wb-021.9's row, then wb-021.6's), and each call reads and parses the whole export, so its wall follows the
 * export's size and the host's load, not its judgements. Measured: 1030 ms file-alone at load1 about 26 (base 4bfe0ac1, an
 * export of 82704321 bytes and 1225 rows; the two whole-export reads alone took 909-994 ms in a plain node run, three runs at
 * load1 about 16); 1686 ms in that gate's merge-tree targeted run (187 files, load1 73.84 at start); 5152 ms in the merge-tree
 * targeted run of wb-021.9's refusal #6 (178 files, load1 129.71 at start), where it timed out at vitest's default 5000 ms
 * (refusal #6 F3). 60000 ms is 11.6 x that 5152 ms wall. vitest fails a synchronous body that outran its budget only once the
 * body has finished, so the budget decides whether a finished ANCHOR fails; it never stops or shortens one.
 */
const ANCHOR_BUDGET_MS = 60_000;

describe("APO judge census (wb-021.9 cut #7): the five clauses, the three folded members and the refusal #1, #2, #5 and #6 witnesses over the landed judge", () => {
  it("SHAPE: the rows, each case's title digest and probe ids with text digests, the MUTANTS pairs and the probe count equal their frozen literals", () => {
    expect(ROWS.map(row => `${row.id} ${row.label}:${row.pins.join(",")}`)).toEqual(FROZEN_ROWS);
    expect(PINS.map(pin => pin.id)).toEqual(ROWS.flatMap(row => row.pins));
    expect(PINS.map(pin => `${pin.id}#${digest(pin.title)}:${pin.probes.map(probe => `${probe.id}#${digest(probe.text)}`).join(",")}`)).toEqual(FROZEN_PROBES);
    expect(Object.entries(MUTANTS).map(([member, pin]) => `${member}=${pin}`)).toEqual(FROZEN_MUTANTS);
    const ids = PINS.flatMap(pin => pin.probes.map(probe => probe.id));
    expect(new Set(ids).size).toBe(ids.length);
    expect(ids).toHaveLength(544);
    const memberPins = ROWS.filter(row => row.id !== "G24").flatMap(row => row.pins);
    expect(Object.values(MUTANTS)).toEqual(memberPins);
  });

  it("ANCHOR: U1..U5 match wb-021.9's description (clause quotes, G16 counts, the 8000); the G16 pairs match refusal #4's member record in wb-021.6's notes; R-B205 and G24 match wb-021.9's notes (the fold record, the refusal #1 witness ids); MUTANTS names match wb-021.6's notes; the W17 probes match refusal #6's UNMET list and F5 in wb-021.9's notes", { timeout: ANCHOR_BUDGET_MS }, ({ task }) => {
    expect(task.timeout, "ANCHOR's own budget (wb-coyr): 60000 ms, never vitest's default 5000 ms").toBe(60_000);
    const { description, notes } = exportRow("wb-021.9");
    expect(description, "wb-021.9 description").not.toBe("");
    const clauses = description.split("\n").filter(line => /^- U[1-5] /.test(line));
    const duties = ROWS.filter(row => /^U[1-5]$/.test(row.id));
    expect(clauses.map(line => /^- (U[1-5]) /.exec(line)?.[1])).toEqual(duties.map(row => row.id));
    for (const [index, duty] of duties.entries()) {
      const clause = clauses[index] ?? "";
      const head = /^- (U[1-5]) (.+?) \((\d+)(?: mutants)?\): /.exec(clause);
      expect(head?.[2]).toBe(duty.label);
      expect(clause.slice(head?.[0].length ?? 0).replace(/\.$/, "")).toBe(duty.pins.map(id => pinNamed(id).quote).join("; "));
      const members = Object.entries(MUTANTS).filter(([member, pin]) => member.startsWith("G16-") && duty.pins.includes(pin));
      expect(members.length, `${duty.id}: the clause's own mutant count`).toBe(Number(head?.[3]));
    }
    const past = Number(/a NUL past the first (\d+) characters/.exec(clauses[0] ?? "")?.[1]);
    expect(past).toBeGreaterThan(0);
    expect(pinNamed("UNITS-NUL").probes.some(probe => probe.text.indexOf(NUL) >= past), "a NUL past the clause's own count").toBe(true);
    const fold = notes.slice(notes.indexOf("RULE19 DEPENDENCY INVERSION R-B205"), notes.indexOf("rule19-invert idem")).split("\n").filter(line => /^U[1-3]-/.test(line));
    const folded = Object.entries(MUTANTS).filter(([member]) => member.startsWith("GP18-"));
    expect(fold).toHaveLength(folded.length);
    for (const [member, pinId] of folded) {
      const written = new RegExp(`-${member.toUpperCase()}-\\d+-0-39-`);
      const line = fold.find(entry => written.test(entry)) ?? "";
      expect(line, `${member} in the R-B205 fold record, as that record writes it`).not.toBe("");
      expect(rowNamed("R-B205").pins).toContain(pinId);
      const tail = line.includes("-PLANTS-P-") ? line.slice(line.indexOf("-PLANTS-") + 8).split("-P-").map((part, index) => (index === 0 ? part : `P-${part}`)) : [];
      for (const plant of tail) expect(pinNamed(pinId).probes.map(probe => probe.id), `${plant} named by the fold record`).toContain(plant);
    }
    const start = notes.indexOf("GATE VERDICT wb-021.9: REFUSED (RESPIN)");
    expect(start).toBeGreaterThanOrEqual(0);
    const refusal = notes.slice(start, notes.indexOf("BIND STEPS AFTER THIS NOTE", start));
    const witnesses = [...new Set(refusal.match(/\bW-[A-Z0-9]+(?:-[A-Z0-9]+)*/g) ?? [])];
    expect(witnesses).toHaveLength(28);
    const held = new Set(PINS.flatMap(pin => pin.probes.map(probe => probe.id)));
    for (const witness of witnesses) expect(held.has(witness), `${witness}, named by the refusal #1 note, is a probe`).toBe(true);
    for (const id of rowNamed("G24").pins) expect(pinNamed(id).probes.some(probe => witnesses.includes(probe.id)), `${id} holds a witness the note names`).toBe(true);
    const sixth = notes.indexOf(UNMET_6);
    expect(sixth, "refusal #6's UNMET list in wb-021.9's notes").toBeGreaterThanOrEqual(0);
    const items = notes.slice(sixth, notes.indexOf("\nRED (record.red verbatim):", sixth)).split("\n").filter(line => /^- U[1-6]: /.test(line));
    expect(items.map(item => item.slice(2, 4)), "refusal #6's six UNMET items").toEqual(["U1", "U2", "U3", "U4", "U5", "U6"]);
    const f5At = notes.indexOf(F5_6, sixth);
    expect(f5At, "refusal #6's F5 bullet").toBeGreaterThanOrEqual(0);
    const f5 = notes.slice(f5At, notes.indexOf("\n", f5At));
    const records = [...items.map(item => ({ caseId: /Claim words: the ([A-Z-]+) title/.exec(item)?.[1] ?? "", span: item.slice(0, item.indexOf("Twins")) })), { caseId: f5.includes("JUDGE-EFFECT's 'a member call's argument") ? "JUDGE-EFFECT" : "", span: f5 }];
    const pages: string[] = [];
    for (const { caseId, span } of records) {
      const ids = [...new Set(span.match(/\bW17-[A-Z0-9]+(?:-[A-Z0-9]+)*/g) ?? [])];
      expect(ids.length, `${caseId}: the pages refusal #6 names for it`).toBeGreaterThan(0);
      for (const page of ids) expect(pinNamed(caseId).probes.map(probe => probe.id), `${page}, which refusal #6 names, is a probe of ${caseId}`).toContain(page);
      pages.push(...ids);
    }
    expect(pages, "refusal #6's 34 witnesses and F5's page").toHaveLength(35);
    const w17 = PINS.flatMap(pin => pin.probes.map(probe => probe.id)).filter(id => id.startsWith("W17-"));
    expect([...w17].sort(), "the census's W17 probes are exactly the pages refusal #6 names").toEqual([...pages].sort());
    const parent = exportRow("wb-021.6").notes;
    for (const member of Object.keys(MUTANTS)) expect(parent, `${member}, named by the wb-021.6 refusals`).toContain(member);
    const opening = parent.indexOf(G16_RECORD);
    expect(opening, "refusal #4's member record in wb-021.6's notes").toBeGreaterThanOrEqual(0);
    const record = parent.slice(opening + G16_RECORD.length, parent.indexOf(". Two more survivors", opening));
    const named = [...record.matchAll(/(G16-[A-Za-z0-9-]+) \(([^)]+)\)/g)].map(match => ({ member: match[1] ?? "", plants: (match[2] ?? "").split(", ") }));
    expect(
      named.map(entry => entry.member),
      "refusal #4's G16 members, in MUTANTS' order",
    ).toEqual(Object.keys(MUTANTS).filter(member => member.startsWith("G16-")));
    for (const { member, plants } of named) {
      const pinId = MUTANTS[member] ?? "";
      for (const plant of plants) expect(pinNamed(pinId).probes.map(probe => probe.id), `${plant}, which refusal #4's record names for ${member}, is a probe of ${pinId}`).toContain(plant);
    }
  });

  it("COVERAGE: the white-space, BLANK, negation-word and wrapper families hold a probe for every member their outside definition names, and U3's every footnote reference a line of two or more", () => {
    const whiteSpace = codePointsWhere(char => /^\s$/.test(char));
    expect(whiteSpace.map(hex)).toHaveLength(25);
    const blank = codePointsWhere(char => BLANK.test(char)).filter(point => point !== 0x0a);
    expect(blank.map(hex)).toHaveLength(25);
    const lines = (id: string): string[] => pinNamed(id).probes.flatMap(probe => probe.text.split("\n"));
    for (const point of whiteSpace.filter(entry => entry !== 0x0a)) {
      const char = String.fromCodePoint(point);
      expect(lines("UNITS-OTHER").some(line => line.length > 0 && [...line].every(entry => entry === char)), `UNITS-OTHER: a ${hex(point)} line`).toBe(true);
    }
    for (const point of whiteSpace) {
      const char = String.fromCodePoint(point);
      expect(pinNamed("CARRIERS-SPLIT").probes.some(probe => cooked(probe).includes(`not${char}really${char}very`)), `CARRIERS-SPLIT: ${hex(point)}`).toBe(true);
      expect(pinNamed("BINDING-SQUEEZE").probes.some(probe => new RegExp(`2026-10-18(?:${escapedWord(char)})+program`).test(probe.text)), `BINDING-SQUEEZE: ${hex(point)}`).toBe(true);
    }
    const crossings = pinNamed("VIEW-OPACITY").probes.map(probe => {
      const at = probe.text.split("\n").findIndex(line => line.endsWith("<!-- open"));
      const open = probe.text.split("\n")[at] ?? "";
      const crossing = probe.text.split("\n")[at + 1] ?? "";
      const prefix = open.slice(0, open.length - "<!-- open".length);
      return crossing.startsWith(prefix) ? crossing.slice(prefix.length) : crossing;
    });
    for (const point of blank) expect(crossings, `VIEW-OPACITY: a ${hex(point)} crossing line`).toContain(String.fromCodePoint(point));
    expect(crossings).toContain("");
    expect(pinNamed("VIEW-FOOTREF").quote, "the U3 clause quote this requirement reads").toContain("every footnote reference");
    expect(lines("VIEW-FOOTREF").some(line => (line.match(/\[\^[^\]\n]+\]/g) ?? []).length >= 2), "VIEW-FOOTREF: a line of two or more footnote references").toBe(true);
    const words = /\(\?:([^)]*)\)/.exec(NEGATION_BEFORE.source)?.[1]?.split("|") ?? [];
    expect(words).toHaveLength(10);
    for (const word of words) {
      for (const form of caseForms(word)) {
        const before = new RegExp(`(?<![\\p{L}'])${escapedWord(form)} (?:design-stage|non-effectful)`, "u");
        expect(pinNamed("CARRIERS-NEG").probes.some(probe => before.test(probe.text)), `CARRIERS-NEG: ${form}`).toBe(true);
      }
    }
    for (const id of ["EFFECT-KEY", "EFFECT-ELEMENT"]) {
      const chains = pinNamed(id).probes.map(wrapperChain);
      for (const kind of WRAPPERS) expect(chains.some(chain => chain.join() === kind), `${id}: ${kind} alone`).toBe(true);
      for (const outer of WRAPPERS) {
        for (const inner of WRAPPERS) {
          expect(chains.some(chain => holdsPair(chain, outer, inner)), `${id}: ${outer} over ${inner}`).toBe(true);
        }
      }
    }
  });

  it("FORMS: each enumeration a title spells verbatim holds a probe for every member it names (VIEW-FOOTREF's label forms, JUDGE-CARRIERS' phrases, case forms, inside kinds and separators, the typed wrappers, JUDGE-VIEW's fences, JUDGE-TEMPLATE's escapes, and the place enumerations of FOLDED-CV, FOLDED-EC, JUDGE-OWES and JUDGE-EFFECT)", () => {
    const footref = pinNamed("VIEW-FOOTREF");
    expect(footref.title).toContain(`a label holding ${spelled(LABEL_FORMS.map(([name]) => name), "or")}, a ${LONG_LABEL}-character label`);
    const labels = footref.probes.flatMap(probe => (probe.text.match(FOOTNOTE.reference) ?? []).map(reference => reference.slice(2, -1)));
    for (const [name, chars] of LABEL_FORMS) expect(labels.some(label => [...chars].every(char => label.includes(char))), `VIEW-FOOTREF: a label holding ${name}`).toBe(true);
    expect(labels.some(label => label.length === LONG_LABEL), `VIEW-FOOTREF: a ${LONG_LABEL}-character label`).toBe(true);

    const carriers = pinNamed("JUDGE-CARRIERS");
    const followed = (rest: string): boolean => carriers.probes.some(probe => probe.text.includes(`design-stage${rest}`) || probe.text.includes(`non-effectful${rest}`));
    expect(carriers.title).toContain(`${spelled(AFTER_PHRASES, "and")} in ${spelled(CASE_NAMES, "and")} case right after a carrier and a space cancel it`);
    for (const phrase of AFTER_PHRASES) {
      for (const [index, form] of caseForms(phrase).entries()) expect(followed(` ${form}.`), `JUDGE-CARRIERS: ${phrase} in ${CASE_NAMES[index] ?? ""} case`).toBe(true);
    }
    const spaced = AFTER_PHRASES.filter(phrase => phrase.includes(" "));
    expect(carriers.title).toContain(`${spelled(spaced, "and")} each with ${spelled(INSIDE_KINDS.map(([name]) => name), "or")} inside cancel it`);
    for (const phrase of spaced) {
      for (const [name, point] of INSIDE_KINDS) expect(followed(` ${phrase.replace(" ", String.fromCodePoint(point))}.`), `JUDGE-CARRIERS: ${phrase} with ${name} inside`).toBe(true);
    }
    expect(carriers.title).toContain(`no longer after a carrier and ${spelled(AFTER_SEPARATORS.map(separator => `'${separator}'`), "or")} and No longer after a carrier and '. ' cancel it`);
    for (const separator of AFTER_SEPARATORS) expect(followed(`${separator}no longer.`), `JUDGE-CARRIERS: '${separator}' before no longer`).toBe(true);
    expect(followed(". No longer."), "JUDGE-CARRIERS: '. ' before No longer").toBe(true);

    for (const id of ["EFFECT-KEY", "EFFECT-ELEMENT"]) {
      expect(pinNamed(id).title).toContain(`under ${spelled(KEY_TYPED, "and")} alone`);
      for (const form of KEY_TYPED) expect(pinNamed(id).probes.some(probe => probe.text.includes(`[${wrapped('"effectClass"', form)}]`)), `${id}: ${form} alone`).toBe(true);
    }
    const effect = pinNamed("JUDGE-EFFECT");
    const typed = (value: string): string[] => VALUE_TYPED.map(form => form.replace("VALUE", value));
    const literal = (value: string): string[] => VALUE_TYPED.filter(form => form.includes("VALUE")).map(form => form.replace("VALUE", value));
    expect(effect.title).toContain(`under ${spelled(typed("write"), "and")} alone; read, a template read and read under the same wrappers (${spelled(literal("read"), "and")} for the literal types) are not`);
    for (const value of ["write", "read"]) {
      for (const form of typed(value)) expect(effect.probes.some(probe => probe.text.includes(`effectClass: ${wrapped(`"${value}"`, form)} }`)), `JUDGE-EFFECT: ${value} under ${form}`).toBe(true);
    }

    const view = pinNamed("JUDGE-VIEW");
    expect(view.title).toContain("the info line of a fence of three or four backticks or tildes, at column zero or three spaces in, shows nothing");
    for (const mark of FENCE_MARKS) {
      for (const count of [3, 4]) {
        for (const indent of [0, 3]) {
          const info = `${" ".repeat(indent)}${mark.repeat(count)}apo design-stage non-effectful`;
          expect(view.probes.some(probe => probe.text.split("\n")[0] === info), `JUDGE-VIEW: the info line ${JSON.stringify(info)}`).toBe(true);
        }
      }
    }

    const template = pinNamed("JUDGE-TEMPLATE");
    for (const [name, spelling] of TEMPLATE_ESCAPES) {
      expect(template.title).toContain(`${name} in the head or the later part`);
      const at = (probe: Probe): number => probe.text.indexOf(spelling);
      expect(template.probes.some(probe => at(probe) >= 0 && at(probe) < probe.text.indexOf(SUBSTITUTION)), `JUDGE-TEMPLATE: ${name} in the head`).toBe(true);
      expect(template.probes.some(probe => probe.text.indexOf("}") >= 0 && at(probe) > probe.text.indexOf("}")), `JUDGE-TEMPLATE: ${name} in the later part`).toBe(true);
    }
    for (const [id, phrase, places] of PLACE_FORMS) {
      const pin = pinNamed(id);
      expect(pin.title, `${id}: its title spells ${JSON.stringify(phrase)}`).toContain(phrase);
      for (const place of places) expect(pin.probes.some(probe => place.test(`${probe.path}:${probe.text}`)), `${id}: a probe in the shape ${place.source}`).toBe(true);
    }
  });

  it("RUN GUARD: one judgeFiles call over each case's probes together raises the run guard by one and reads their kinds, unit and string counts summed and their citations, banner modules and findings joined in probe order", () => {
    for (const pin of PINS) {
      const before = READS.calls;
      const reading = judgeFiles(pin.probes.map(probe => ({ path: probe.path, text: probe.text })));
      expect(READS.calls, `${pin.id}: one run-guard count for its ${pin.probes.length} probes`).toBe(before + 1);
      const kinds: Record<FileKind, number> = { lock: 0, binary: 0, markdown: 0, script: 0, text: 0 };
      for (const probe of pin.probes) {
        for (const kind of Object.keys(kinds) as FileKind[]) kinds[kind] += probe.expected.kinds[kind];
      }
      const sum = (count: (probe: Probe) => number): number => pin.probes.reduce((total, probe) => total + count(probe), 0);
      expect(reading, `${pin.id}: its probes judged in one call`).toEqual({
        kinds,
        units: sum(probe => probe.expected.units),
        strings: sum(probe => probe.expected.strings),
        citing: pin.probes.flatMap(probe => probe.expected.citing),
        banner: pin.probes.flatMap(probe => probe.expected.banner),
        findings: pin.probes.flatMap(probe => probe.expected.findings),
      });
    }
  });

  for (const pin of PINS) {
    it(`${pin.id}: ${pin.title}`, () => {
      for (const probe of pin.probes) {
        const before = READS.calls;
        const reading = judgeFiles([{ path: probe.path, text: probe.text }]);
        expect(READS.calls, `${pin.id}/${probe.id}: one run-guard count per judge call`).toBe(before + 1);
        const binding = probe.bound === undefined ? [] : bindingOf(reading.citing, probe.bound);
        expect({ ...reading, binding }, `${pin.id}/${probe.id}: the probe's literal reading`).toEqual(probe.expected);
        if (probe.causes !== undefined) expect(causesOf(probe.path, probe.text), `${pin.id}/${probe.id}: causes`).toEqual(probe.causes);
      }
    });
  }
});
